"""CSV merger for combining flashcard files."""

from __future__ import annotations

import csv
import os
import tempfile
from collections.abc import Iterator
from pathlib import Path
from typing import TYPE_CHECKING

from flashcards_generator.domain.exceptions import CSVMergeError

if TYPE_CHECKING:
    from flashcards_generator.application.dto.merge_request import (
        MergeCsvRequest,
    )


class CsvMerger:
    """Merge multiple CSV flashcard files into one."""

    @staticmethod
    def merge(request: MergeCsvRequest) -> int:
        """Merge all CSV files in folder_path into single output file.

        Args:
            request: MergeCsvRequest with folder, output name, dedup flag

        Returns:
            Number of rows written to merged file

        Raises:
            CSVMergeError: If folder doesn't exist or merge fails
        """
        output_path = request.folder_path / request.output_filename
        try:
            csv_files = CsvMerger._source_files(request, output_path)
            return CsvMerger._write_rows(
                output_path, csv_files, deduplicate=request.deduplicate
            )

        except CSVMergeError:
            raise
        # This application boundary must translate every merge failure consistently.
        except Exception as e:
            raise CSVMergeError(request.folder_path, str(e)) from e

    @staticmethod
    def _source_files(
        request: MergeCsvRequest, output_path: Path
    ) -> list[Path]:
        if not request.folder_path.exists():
            raise CSVMergeError(request.folder_path, "Folder does not exist")
        pattern = "**/*.csv" if request.recursive else "*.csv"
        csv_files = [
            path
            for path in sorted(request.folder_path.glob(pattern))
            if path != output_path
        ]
        if not csv_files:
            raise CSVMergeError(
                request.folder_path, "No CSV files found in folder"
            )
        return csv_files

    @staticmethod
    def _write_rows(
        output_path: Path,
        csv_files: list[Path],
        *,
        deduplicate: bool,
    ) -> int:
        temporary_path: Path | None = None
        try:
            with tempfile.NamedTemporaryFile(
                mode="w",
                newline="",
                encoding="utf-8",
                dir=output_path.parent,
                prefix=f".{output_path.name}.",
                suffix=".tmp",
                delete=False,
            ) as out_f:
                temporary_path = Path(out_f.name)
                writer = csv.writer(out_f, quoting=csv.QUOTE_ALL)
                rows = CsvMerger._iter_rows(csv_files)
                if deduplicate:
                    rows = CsvMerger._deduplicated(rows)
                total_rows = 0
                for front, back in rows:
                    writer.writerow([front, back])
                    total_rows += 1
                out_f.flush()
                os.fsync(out_f.fileno())

            temporary_path.replace(output_path)
            return total_rows
        except Exception:
            if temporary_path is not None:
                temporary_path.unlink(missing_ok=True)
            raise

    @staticmethod
    def _iter_rows(csv_files: list[Path]) -> Iterator[tuple[str, str]]:
        for csv_file in csv_files:
            with open(csv_file, newline="", encoding="utf-8") as in_f:
                for row_number, row in enumerate(csv.reader(in_f), start=1):
                    if len(row) < 2:
                        continue
                    if len(row) != 2:
                        raise CSVMergeError(
                            csv_file,
                            f"Row {row_number} must contain exactly 2 columns; "
                            f"found {len(row)} columns",
                        )
                    yield row[0], row[1]

    @staticmethod
    def _deduplicated(
        rows: Iterator[tuple[str, str]],
    ) -> Iterator[tuple[str, str]]:
        seen: set[tuple[str, str]] = set()
        for row in rows:
            key = (row[0].strip(), row[1].strip())
            if key not in seen:
                seen.add(key)
                yield row

"""DTOs for framework-neutral application workflows."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from flashcards_generator.application.dto.generate_request import (
    GenerateFlashcardsRequest,
)

DEFAULT_ANKI_CONNECT_URL = "http://127.0.0.1:8765"


@dataclass(frozen=True, slots=True)
class AnkiExportOptions:
    """Optional configuration for exporting generated decks to Anki."""

    deck_name: str
    url: str = DEFAULT_ANKI_CONNECT_URL
    api_key: str | None = None


@dataclass(frozen=True, slots=True)
class GenerateWorkflowRequest:
    """Request for the complete generation workflow."""

    generation_request: GenerateFlashcardsRequest
    language: str = "pt_BR"
    check_auth: bool = True
    anki: AnkiExportOptions | None = None


@dataclass(frozen=True, slots=True)
class CleanupRequest:
    """Request to remove all or recently created NotebookLM notebooks."""

    days: int | None = None
    check_auth: bool = True

    def __post_init__(self) -> None:
        if self.days is not None and self.days <= 0:
            raise ValueError("days must be positive")


@dataclass(frozen=True, slots=True)
class AuthStatus:
    """Result of checking NotebookLM authentication."""

    authenticated: bool
    message: str = ""


@dataclass(frozen=True, slots=True)
class MergeOutcome:
    """Result of merging CSV files."""

    output_path: Path
    rows_written: int


@dataclass(frozen=True, slots=True)
class CleanupOutcome:
    """Result of deleting selected NotebookLM notebooks."""

    deleted: int
    failed: int

    @property
    def succeeded(self) -> bool:
        """Return whether every selected notebook was deleted."""
        return self.failed == 0
